from pathlib import Path
import json,datetime,base64,html
import pandas as pd
O=Path.cwd();R=O/'report';D=O/'results';now=datetime.datetime.now(datetime.timezone.utc).isoformat()
orig=json.loads((D/'ORIGINAL31_RESULT.json').read_text());bulk=json.loads((D/'BULK_RESULT.json').read_text());om=pd.read_csv(D/'original31_models.tsv',sep='\t');bm=pd.read_csv(D/'bulk_models.tsv',sep='\t');src=pd.read_csv(D/'identity_source_summary.tsv',sep='\t');con=pd.read_csv(D/'identity_source_contrasts.tsv',sep='\t');state=pd.read_csv(D/'mesothelial_state_models.tsv',sep='\t');qa=json.loads((O/'NUMERICAL_QA.json').read_text())
def tab(df):return '<div class="tw">'+df.to_html(index=False,border=0,na_rep='不可评估',float_format=lambda x:f'{x:.6g}')+'</div>'
def img(n,c):return '<figure><img src="data:image/png;base64,'+base64.b64encode((O/'figures'/n).read_bytes()).decode()+'" alt="'+html.escape(c)+'"><figcaption>'+c+'</figcaption></figure>'
def detail(t,b):return '<details><summary>'+t+'</summary>'+b+'</details>'
refs=[('原31患者研究及公开CHP资料','https://www.frontiersin.org/journals/oncology/articles/10.3389/fonc.2022.939969/full'),('作者数据仓库9t86hd78sj','https://data.mendeley.com/datasets/9t86hd78sj/1'),('配对组织GSE314812','https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE314812'),('腹腔细胞GSE228598','https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE228598'),('GSE228598原研究','https://pmc.ncbi.nlm.nih.gov/articles/PMC11012629/'),('GSE234129','https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE234129'),('GSE239676','https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE239676'),('间皮标志物原始研究（含Cgnl1表达记录）','https://pmc.ncbi.nlm.nih.gov/articles/PMC3184985/'),('间皮细胞与胃癌侵袭的既有研究','https://pubmed.ncbi.nlm.nih.gov/27895076/'),('CGNL1连接处肌球蛋白组织功能','https://pmc.ncbi.nlm.nih.gov/articles/PMC10202830/')]
body=f'''<header><p class="tag">CGNL1 · 胃癌腹膜播散 · 实际数据验证 v1</p><h1>组织关联获得支持，<br>腹腔间皮样来源值得优先验证</h1><p class="lead">本轮有继续推进的依据。可推进的是CGNL1组织关联、细胞来源及其与腹膜播散状态的关系；尚不能确定“癌细胞驱动”“间皮屏障破坏”或“促进定植”机制。</p><p class="meta">{now} UTC（纽约当地2026-10-15）。内部审核报告；原始数据、脚本、失败记录与完整统计均留在sgs10。旧研究成果未覆盖。</p></header>
<section class="verdict"><h2>建议继续，但先把细胞来源与病变状态联系起来</h2><p><strong>优先验证的问题：</strong>胃癌腹膜播散相关的CGNL1组织信号，是否对应可区分于细胞数量变化的宿主间皮/基质状态，并与腹膜播散易感或病灶形成有关？</p><p>临床过程是胃癌的腹膜播散。现有结果支持CGNL1与该过程存在组织层面的关联，并提示腹腔中的非免疫来源。当前最重要的新增信息应是“哪些细胞在什么临床状态下改变”，而不是立即追加通路、空间邻域或预后评分。</p><p><strong>阶段决策：</strong>进入有明确验收门槛的下一轮来源/状态验证；暂不将CGNL1写成已确立的机制靶点。组织关联与间皮样细胞富集分别成立于各自材料，尚不能自动连成同一因果链。</p></section>
<section><h2>实际取得并检查了54份CHP文件和新的作者计数文件</h2>{tab(pd.DataFrame([['2022原研究','54份CHP：12份文件名标注with PC、19份without PC、23份Healthy','全部与仓库提供的SHA256一致；解码20,866个特征；CGNL1为唯一精确符号行','已分析，标签有文件夹冲突'],['GSE314812','新下载作者RSEM expected-count文件；17对合格原发/腹膜病灶','新下载与已有计数文件字节完全一致；复用原TMM测量并做全库CPM敏感性','已分析，不是原31例的相同对比'],['GSE228598','复用已下载的28个腹腔细胞矩阵，逐样本重读原始UMI','归档哈希一致；按条码核对冻结QC；重建CGNL1来源和严格身份规则','已分析，临床P/Cy逐患者映射未落实'],['GSE234129','复用实际计数与作者注释','以非免疫亚群补充来源检查；没有强行赋予恶性上皮标签','描述性支持，非完整肿瘤细胞图谱'],['GSE239676','下载官方特征表及尝试元数据','完成的特征表只有8,630行，无CGNL1/ENSG00000128849；元数据传输未完成','不用于CGNL1验证；缺失不当作零表达']],columns=['来源','实际材料','核查','状态']))}<p>CHP是作者处理后的基因表达结果，不是原始测序reads；其内部声明为log2 scaled-RPM，数值范围与该尺度一致。没有将CHP、RSEM expected counts及单细胞UMI混为一种测量单位。</p></section>
<section><h2>原31份肿瘤文件重现了CGNL1与腹膜受累的正向关联</h2><p>按作者文件名分组，with PC组平均表达5.982，without PC组3.956，差值+2.026 log2 scaled-RPM，对应几何倍数4.073；Welch P=0.006086，95%区间为+0.627至+3.425。Mann–Whitney P=0.01414，逐一样本排除后效应保持正向。</p><p>这重现了论文的变化方向，但<strong>没有精确复现论文FC=4.82、P=0.0081</strong>。本轮直接分析公开CHP；作者完整TAC设置和逐患者临床映射未取得，数值差异原因尚未核定。公开材料只提供23份Healthy文件，未假定其与31份肿瘤一一配对。</p>{tab(pd.DataFrame([['with PC',12,orig['with_mean']],['without PC',19,orig['without_mean']],['Healthy（未配对）',23,4.536734]],columns=['文件组','样本数','CGNL1平均log2 scaled-RPM']))}<p>加入处理程序版本、再加入六类来源代理后，CGNL1目标效应仍为正，完整模型P=0.03684。该结果保留为组织层面的关联，不代表已排除分期、Lauren类型或全部混杂。</p>{tab(om)}<p><strong>多重检验口径：</strong>上表FDR仅对应本次预定的三个CGNL1条件模型。若把所有20,866个测得特征的Welch检验作为家族，CGNL1 FDR=0.8714。本研究是根据已发表线索选择目标后的再分析，不能借缩小家族把原全特征筛选改写成校正后发现。原始P&lt;0.05的候选资格保留。</p></section>
<section><h2>独立配对组织保留升高方向，证据强度依赖保存方式与模型</h2><p>GSE314812的17对患者中11对腹膜病灶CGNL1高于原发灶，平均差+0.8186、中位差+0.5176 TMM log2CPM。预定精确配对符号秩检验P=0.07968，未达到名义显著。校正FFPE/冰冻保存方式的配对差异后，效应+0.9487、P=0.02181、三模型家族FDR=0.06544，为名义显著。</p>{tab(bm)}<p>加入六类来源代理后效应仍正且并未衰减，但区间变宽，P=0.1958。因此不能宣称“信号已经被细胞组成解释掉”，也不能宣称独立细胞内变化成立。保存方式相同的5对中4对升高；全库CPM替代归一化保留11/17升高，平均差+0.8600。它们是敏感性支持，不增加独立患者数。</p><p>这17对回答“同一患者的原发灶与腹膜病灶是否不同”；原31例回答“有无腹膜受累患者的原发肿瘤是否不同”。两种估计对象互补，不能将48例混合为同一个检验或称为完全相同终点的外部复现。</p>{img('01_core_evidence.png','图1：原31份肿瘤文件、17对组织和同患者细胞来源比较。各面板使用不同测量单位及估计对象，未合并P值或样本量。')}</section>
<section><h2>严格身份规则仍显示CGNL1偏向间皮样细胞</h2><p>首先沿用不含CGNL1的旧谱系规则，发现间皮样来源线索；随后在新规则计算前记录方案，要求UPK3B/LRRN4至少一个检出，并有WT1/CALB2/MSLN至少一个支持，排除明显髓系/淋巴来源。保守上皮样群体要求EPCAM及至少两个角蛋白，同时不检出上述特异间皮标志。该补充是事后身份敏感性，仍不等同病理确证或DNA恶性身份验证。</p><p>每群至少20细胞时，15位患者具有合格严格间皮样群体，15位均检出CGNL1；患者检出率中位数16.05%。10位可与同患者保守上皮样细胞比较，10/10间皮样表达更高，平均差+0.1893 ln(1+CP10k)，P=0.001953、两比较家族FDR=0.001953。与巨噬细胞比较的15位也均更高。</p>{tab(con)}<p>排除高癌细胞代理群后，13位合格患者仍全部检出目标。提高到每群至少50细胞，严格间皮样保留9位且均检出，但与上皮样的共同合格患者仅2位；该门槛不作推断，方向2/2保留。这里支持的是来源差异，不能解释为播散使间皮细胞CGNL1升高。</p>{tab(src)}<p>GSE234129的作者注释中，CGNL1计数主要落在少量成纤维、内皮、间皮及血管平滑肌细胞；19,042个免疫细胞合计只有3个目标计数。该对象没有提供完整恶性上皮群体，不能用它宣称癌细胞不表达CGNL1。两个单细胞来源也未做跨研究患者身份去重，未将其患者数合并。</p>{img('02_source_and_limits.png','图2：严格来源定义下的患者表达；右图显示调整深度及间皮身份后，三个状态读出均未达到名义显著。')}</section>
<section><h2>现有RNA读出尚未建立连接、间质化或增殖机制</h2><p>15位严格间皮样患者中，CGNL1与增殖分数的未调整Spearman相关为−0.6607，P=0.00733、三程序FDR=0.02199。控制测序深度及间皮身份代理后，目标效应P=0.6929；连接和间质程序也均未达到名义显著。</p>{tab(state)}<p>因此当前不使用“CGNL1抑制增殖”“推动间皮间质转化”“破坏连接”作为结论。蛋白定位、机械张力、完整间皮屏障、实际穿越能力和RNA分数是不同终点。</p></section>
<section><h2>关键数据问题保留为审核事项</h2>{tab(pd.DataFrame([['GC-Q01','原仓库文件夹名冲突','名为Tumors without peritoneal carcinomatosis的文件夹实际装12个Tumor with PC文件；New folder装19个Tumor without PC文件。','本轮使用文件名，数量与论文12/19一致；未按表达方向决定分组。CHP内部没有临床标签，个人临床映射尚未核实。'],['GC-Q02','公开文件与论文统计不完全一致','本轮FC=4.073、Welch P=0.006086；论文FC=4.82、P=0.0081。','保留两套数值及分析口径，不宣称完整重现TAC流程。'],['GC-Q03','腹腔样本的临床分组缺口','现有GEO和已检查补充PDF未提供可直接对接P1–P29的逐患者PC/细胞学映射。','不把腹水/冲洗液直接改写成转移阳性/阴性；无法据此检验间皮状态与PC的患者级关系。'],['GC-Q04','一个大队列没有目标','GSE239676公开特征表不包含CGNL1；元数据下载还有截断。','排除该输入，不将缺失当低表达，不在截断元数据上计算正式样本量。'],['GC-Q05','间皮样标签仍是标志物资格','来源规则与癌细胞代理敏感性均不使用CGNL1，但没有DNA或病理确证。','继续验证需有完整恶性/间皮标注或可核实的组织来源。']],columns=['编号','事项','证据','处理/验收要求']))}</section>
<section><h2>创新性应落在疾病相关状态，而不是重复发现间皮表达</h2><p>原研究已经披露胃癌腹膜受累相关的CGNL1表达线索；既有间皮转录研究也列出过Cgnl1。间皮细胞支持胃癌侵袭以及CGNL1的连接组织功能分别已有研究。因此，“该基因在间皮表达”“腹膜病灶比原发灶高”本身不足以构成新机制主线。</p><p>本轮更有价值的变化，是实际数据把优先来源指向宿主间皮/基质，使后续能够检验一个明确竞争解释：组织CGNL1升高究竟只是细胞组成变化，还是伴随特定宿主状态，并与腹膜播散易感或病灶形成有关。该状态及临床关系仍待验证，没有通过相关研究的缺失来宣称首创。</p></section>
<section class="verdict"><h2>下一阶段只推进能解决关键缺口的验证</h2><ol><li><strong>先补患者级临床锚点：</strong>取得可核实的PC、腹腔细胞学、治疗时间和取样方式映射；或使用另一个已具备这些条件的队列。然后在同一细胞来源内检验CGNL1差异，不以细胞总数扩大n。</li><li><strong>再分清肿瘤与宿主来源：</strong>优先实测CGNL1、具有合格间皮与恶性细胞标注的资料。组织定位或空间材料应为这一问题服务，不预设必须使用某个算法。</li><li><strong>有疾病相关状态后才扩展机制：</strong>连接/力学、间皮转化或再黏附等读出需有各自直接证据。若只有正常间皮身份标志而没有疾病状态或独立信息，应停止把CGNL1提升为机制主角。</li></ol><p>当前建议是<strong>有条件继续来源和疾病状态验证</strong>，不是立即启动完整机制故事、临床预测模型或多组学包装。</p></section>
<section><h2>Methods</h2><p>下载使用公开官方接口与文件链接，保存URL、退出码、大小和SHA256。CHP使用Calvin二进制结构读取器解析，另用NumPy结构化数组独立核对全部数值。保留重复符号的原始特征行；CGNL1要求唯一精确匹配。原31组使用作者提供的log2 scaled-RPM；Welch为预定主要目标检验，并列稳健线性模型和完整特征家族背景。</p><p>17对配对组织复用已记录的TMM logCPM和患者配对；新下载作者RSEM计数与原输入完全一致。定义腹膜病灶减原发灶，校正保存方式差及六类固定来源代理，使用HC3标准误和残差自由度t检验。以原始P&lt;0.05作为名义筛选标准，按预定同类假设家族报告FDR。</p><p>单细胞从原始矩阵重新汇总，按条码核对冻结QC及注释，保留零表达细胞。每位患者每一来源合计UMI后计算ln(1+CP10k)，另报告检出率。来源比较在同患者内进行；主门槛20细胞、敏感性50细胞。小于10位共同合格患者仅报告描述性效应。本轮未使用细胞级P值。</p><p>身份敏感性和三个状态读出在目标结果已知后另行固定方案，明确为事后探索。冻结方案、原始模型、失败记录均保存，未用更有利的模型覆盖原结果。</p></section>
<section><h2>Discussion与未验证事项</h2><p>当前证据来自不同取样层级：原发组织、腹膜病灶及腹腔液体，不能直接组成纵向或因果链。原31例的文件分组与文件夹冲突、未取得个体临床混杂变量、未精确重现作者TAC处理，以及17对样本的保存方式差异，均限制结论范围。</p><p>RNA代理评分不能消除全部组成影响；完整模型区间变宽不等于已证明无效或组成解释。流体中脱落的间皮样细胞不直接代表完整腹膜屏障，采集方式、治疗和细胞保留过程都可能影响测量。上皮样门控不是恶性身份确证。已有细胞资料的重复使用不增加独立验证次数。</p><p>本轮已经实现实际数据验证，不是仅作文献推断；但尚未证实CGNL1在腹膜播散中的直接功能、预后价值或临床可用性。下一阶段是否值得扩大投入，取决于疾病相关细胞状态能否被验证。</p></section>
<section><h2>完整性验收与记录位置</h2><p>54份CHP的作者SHA256全部一致，双二进制读取一致；新的GSE314812下载与既有输入字节一致。独立矩阵代数重算HC3效应/P，独立复算Welch、配对符号秩、来源比较与BH，最大差异约2.3×10⁻¹⁴。该验收不等于临床标签或细胞身份已被独立确证。</p><p>完整服务器目录：<code>{html.escape(str(O))}</code>。原始/处理输入、代码、失败和日志保存在服务器；本地仅保留审核报告、图件、完整统计与交接材料。</p>{detail('展开原31份肿瘤文件的个体值',tab(pd.read_csv(O/'processed/original31_sample_values.tsv',sep=chr(9))))}{detail('展开17对个体变化',tab(pd.read_csv(D/'bulk_patient_deltas.tsv',sep=chr(9))))}{detail('展开间皮身份覆盖',tab(pd.read_csv(D/'identity_coverage.tsv',sep=chr(9))))}{detail('展开数值验收','<pre>'+html.escape(json.dumps(qa,indent=2))+'</pre>')}</section>
<section><h2>主要来源</h2><ul>{''.join('<li><a href="'+u+'">'+n+'</a></li>' for n,u in refs)}</ul><p class="meta">本轮实际数据验证完成；整个研究项目未宣布完成；报告待用户审核。未向外部对象发送材料。</p></section>'''
css='''body{font-family:"Microsoft YaHei",Arial,sans-serif;background:#eef3f4;color:#21363e;line-height:1.85;margin:0}main{max-width:1120px;margin:30px auto;background:#fff;padding:45px 50px}h1{font-size:31px;line-height:1.4;color:#153f4b}h2{font-size:21px;color:#176b77}.tag,.meta{color:#627b84;font-size:13px}.lead{font-size:17px}.verdict{background:#eef7f3;border-left:5px solid #2c8773;padding:20px 25px}section{margin-top:30px;padding-top:20px;border-top:1px solid #dce6e9}.tw{overflow-x:auto}table{border-collapse:collapse;font-size:13px;min-width:95%;margin:16px 0}th,td{padding:8px 10px;border-bottom:1px solid #d9e4e7;text-align:left;vertical-align:top}th{background:#edf5f6;white-space:nowrap}tr:nth-child(even){background:#f8fafb}img{max-width:100%;height:auto}figure{margin:24px 0}figcaption{font-size:13px;color:#576f78}details{border:1px solid #dce5e8;padding:12px 16px;margin:12px 0}summary{cursor:pointer;color:#176b77}code,pre{overflow-wrap:anywhere;white-space:pre-wrap;font-size:12px}a{color:#176a88}@media(max-width:700px){main{margin:0;padding:22px}h1{font-size:24px}}'''
doc='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CGNL1 胃癌腹膜播散实际数据验证</title><style>'+css+'</style></head><body><main>'+body+'</main></body></html>'
(R/'CGNL1_gastric_peritoneal_validation.html').write_text(doc,encoding='utf-8')
abstract=f'''CGNL1 胃癌腹膜播散：实际数据验证摘要
时间：{now}

结论：有条件继续。实际数据支持组织层面正向关联，并提供跨患者的间皮样细胞来源证据。当前值得推进的是细胞来源及疾病相关状态验证，尚不能宣称癌细胞驱动、间皮屏障破坏或促进定植机制。

实际数据：新下载54份作者CHP（31肿瘤+23未配对Healthy），逐文件SHA256通过；新下载GSE314812作者计数并与旧输入逐字节一致；重读GSE228598的28个原始矩阵和GSE234129的原始计数/作者注释。没有将缺少CGNL1的GSE239676作为验证。

关键结果：
1. 原31份肿瘤文件按文件名分组，12 with PC、19 without PC。CGNL1差值+2.0260 log2 scaled-RPM、几何倍数4.073，Welch P=0.006086。全20,866特征Welch家族FDR=0.8714；本次条件模型家族另列，完整调整模型P/FDR=0.03684。保留为已发表线索的名义支持，不称全基因组校正后发现。
2. 独立17对组织，11对腹膜病灶升高；平均差+0.8186、中位差+0.5176 TMM log2CPM。预定配对检验P=0.07968；保存方式调整P=0.02181、FDR=0.06544；完整组成调整P=0.1958且区间较宽。两个队列回答不同问题，未合并样本量/P。
3. 严格标志物规则留下15位有足够间皮样细胞的患者，15位均检出CGNL1；10位可与同患者保守上皮样比较，10/10间皮样更高，P=0.001953、FDR=0.001953。>=50细胞时相关比较患者减少，方向保留但推断资格不足。
4. 调整深度与身份后，连接、间质化和增殖读出均未获名义显著支持。未调整的增殖负相关保留在完整表中，不能升级成独立机制。

必须保留的数据问题：仓库的一个without PC文件夹装的是12份with PC文件，本轮用文件名且数量与论文一致；CHP内部没有临床标签，个人映射未核实。重算FC/P不等于论文4.82/0.0081，未静默替换。GSE228598缺少可用的逐患者PC/细胞学映射，不能用腹水/冲洗液代替。

优先问题：胃癌腹膜播散相关CGNL1组织信号是否对应宿主间皮/基质状态，并与播散易感或病灶形成有关，而非仅细胞组成不同？
下一步应补齐临床锚点或合格独立材料，并在同一细胞来源内验证。当前不建议继续泛富集或直接扩写机制故事。

完整记录：{O}
报告：CGNL1_gastric_peritoneal_validation.html
'''
(R/'CGNL1_胃癌腹膜播散_审核摘要.txt').write_text(abstract,encoding='utf-8');(O/'REPORT_SOURCES.json').write_text(json.dumps(refs,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps({'report':str(R/'CGNL1_gastric_peritoneal_validation.html'),'bytes':len(doc.encode('utf-8'))},ensure_ascii=False))
